import LeanNative.IR.Types
open LeanNative.IR

/-!
# W3-C1b: 8-lane pure-Lean `ByteArray` vectorization benchmark

Straight-line read-only kernel over one 64-byte `ByteArray` (8 little-endian `UInt64`
lanes). Each lane assembles its word from 8 `ByteArray.uget` reads and mixes it with
`clmul64`/`clmul64Hi` (carry-less multiply, `vpclmulqdq`), 64-bit rotates, and a
Keccak-chi-style three-input boolean fold (`vpternlogq`). Compiled with
`lean-native build-exe` + Clang 23 `-O3 -march=znver5 -mprefer-vector-width=512`,
clang's SLP vectorizer emits `%zmm` code with zero `lean_apply_*`/`lean_alloc_*`
in the kernel bodies.
-/

/-- One lane: little-endian `UInt64` read at byte offset `off` + GF(2^64) / boolean mix. -/
@[noinline, export w3c1b_lane]
def lane (ba : ByteArray) (off : UInt64) (h : off.toNat + 8 ≤ ba.size) : UInt64 :=
  let i := off.toUSize
  let b0 := ba.uget i       (by omega)
  let b1 := ba.uget (i + 1) (by omega)
  let b2 := ba.uget (i + 2) (by omega)
  let b3 := ba.uget (i + 3) (by omega)
  let b4 := ba.uget (i + 4) (by omega)
  let b5 := ba.uget (i + 5) (by omega)
  let b6 := ba.uget (i + 6) (by omega)
  let b7 := ba.uget (i + 7) (by omega)
  let w := b0.toUInt64 ||| (b1.toUInt64 <<< 8) ||| (b2.toUInt64 <<< 16) ||| (b3.toUInt64 <<< 24)
        ||| (b4.toUInt64 <<< 32) ||| (b5.toUInt64 <<< 40) ||| (b6.toUInt64 <<< 48) ||| (b7.toUInt64 <<< 56)
  let m := clmul64 w 0x87c37b911184f4c5
  let n := clmul64Hi w 0x9ae16a3b2f90404f
  let t := w ^^^ ((w <<< 31) ||| (w >>> 33)) ^^^ ((w <<< 17) ||| (w >>> 47))
  (m ^^^ n ^^^ t) ^^^ ((~~~(m ^^^ t)) &&& n)

